script:
frappe.call({
    method: 'mobile_app_360ithub.custom_hr.get_approved_leave_applications',
    callback: function(r) {
        var container = root_element.querySelector('.leave-history-table');
        container.innerHTML = ''; // Clear previous content

        function formatDate(dateStr) {
            if (!dateStr) return "-";
            var parts = dateStr.split('-');
            return parts[2] + '-' + parts[1] + '-' + parts[0];
        }

        // 1. Get the data and count
        var leave_history = (r.message && Array.isArray(r.message)) ? r.message : [];
        var msglength = leave_history.length;

        // 2. ALWAYS Create the heading
        var heading = document.createElement('h3');
        heading.textContent = `(${msglength}) Forthcoming Approved Employee Leaves:`;
        container.appendChild(heading);

        // 3. Conditional Content
        if (msglength > 0) {
            var table = document.createElement('table');
            table.classList.add('table', 'table-bordered');

            var thead = document.createElement('thead');
            var headerRow = document.createElement('tr');
            var headers = ['S.No', 'Employee Name', 'From Date', 'To Date', 'Total Leave Days', 'Approved By'];

            headers.forEach(function(header) {
                var th = document.createElement('th');
                th.setAttribute("style", "background-color:#3498DB;color:white;text-align:left;border:solid 2px #bcb9b4;padding: 8px;");
                th.textContent = header;
                headerRow.appendChild(th);
            });
            thead.appendChild(headerRow);
            table.appendChild(thead);

            var tbody = document.createElement('tbody');
            leave_history.forEach(function(leave, index) {
                var row = document.createElement('tr');

                // Helper for standard text cells
                const createCell = (text) => {
                    var cell = document.createElement('td');
                    cell.textContent = text || '-';
                    cell.setAttribute("style", "border:solid 2px #bcb9b4;padding: 8px;");
                    return cell;
                };

                // Cell 1: S.No
                row.appendChild(createCell(index + 1));

                // Cell 2: Employee Name WITH Hyperlink
                var nameCell = document.createElement('td');
                nameCell.setAttribute("style", "border:solid 2px #bcb9b4;padding: 8px;");

                var link = document.createElement('a');
                // Frappe internal route format
                link.setAttribute('href', '/app/leave-application/' + leave.name);
                link.textContent = leave.employee_name;
                link.setAttribute('style', 'font-weight: bold; color: #1B4F72;');

                nameCell.appendChild(link);
                row.appendChild(nameCell);

                // Cell 3: From Date
                row.appendChild(createCell(formatDate(leave.from_date)));

                // Cell 4: To Date
                row.appendChild(createCell(formatDate(leave.to_date)));

                // Cell 5: Total Leave Days
                row.appendChild(createCell(leave.total_leave_days));

                // Cell 6: Approved By
                row.appendChild(createCell(leave.leave_approver_name));

                tbody.appendChild(row);
            });
            table.appendChild(tbody);
            container.appendChild(table);

        } else {
            // 4. Placeholder
            var placeholder = document.createElement('div');
            placeholder.setAttribute("style", "padding: 30px; text-align: center; color: #888; border: 1px dashed #bcb9b4; border-radius: 4px; background-color: #f9f9f9; margin-top: 10px;");
            placeholder.innerHTML = `
                <div style="font-weight: 500;">No upcoming approved leave</div>
                <div style="font-size: 0.9em;">When leave applications are approved, they will appear here.</div>
            `;
            container.appendChild(placeholder);
        }
    }
});

style:
.table {
    width: 100%;
    border-collapse: collapse;
}
.table, .table th, .table td {
    border: 1px solid #bcb9b4;
    padding: 8px;
    text-align: left;
}
.table th {
    background-color: #3498DB;
    color: white;
}

script:
var current_sort_hr = "desc";
var date_ctrl_hr = null;
var emp_ctrl_hr = null;
var show_all_hr = false;
var hr_cache = {data: []};

function init_hr_dashboard() {
    var container = root_element.querySelector('.absent-table-hr');
    container.style.padding = "10px";
    
    container.innerHTML = `
        <div id="hr-header" style="margin-bottom: 15px;">
            <h3 style="margin: 0 0 12px 0; font-size: 20px; font-weight: bold; color: #172B4D;">
                <span id="hr-count" style="color:#e74c3c;">(0 Pending)</span> Absences 
                <span id="hr-range-text" style="font-weight: normal; color: #444; margin-left: 8px; font-size: 18px;"></span>
            </h3>
            
            <div style="display: flex; align-items: center; gap: 10px; flex-wrap: nowrap;">
                <button id="hr-toggle-btn" class="btn btn-default btn-xs" style="font-weight:bold; color:#444; border: 1px solid #ccc; font-size: 13px; padding: 4px 12px; height: 32px;">Show More</button>
                
                <div style="display: flex; align-items: center; gap: 8px; margin-left: auto;">
                    <button id="hr-refresh" class="btn btn-default btn-sm" style="height:32px; border: 1px solid #d1d8dd;"><i class="fa fa-refresh"></i></button>
                    <div id="hr-emp-filter" style="width:180px;"></div>
                    <div id="hr-date-filter" style="width:230px;"></div>
                    <button id="hr-apply" class="btn btn-primary btn-sm" style="height:32px; padding: 0 15px; font-weight:bold; background-color: #171717; border: none; color: white;">Apply</button>
                </div>
            </div>
        </div>
        
        <div id="hr-table-container"></div>
    `;

    emp_ctrl_hr = frappe.ui.form.make_control({
        df: { fieldtype: 'Link', options: 'Employee', placeholder: 'Filter Employee', only_select: true },
        parent: root_element.querySelector('#hr-emp-filter'),
        render_input: true
    });
    $(emp_ctrl_hr.input).on('keydown keyup keypress', function(e) { e.stopPropagation(); });

    date_ctrl_hr = frappe.ui.form.make_control({
        df: { fieldtype: 'DateRange', placeholder: 'Select Date Range' },
        parent: root_element.querySelector('#hr-date-filter'),
        render_input: true
    });

    var today = frappe.datetime.get_today();
    var month_start = frappe.datetime.month_start();
    date_ctrl_hr.set_value([month_start, today]);
    
    fetch_hr_data(month_start, today);

    $(root_element).find('#hr-apply, #hr-refresh').on('click', function() {
        var val = date_ctrl_hr.get_value();
        fetch_hr_data(val[0], val[1], emp_ctrl_hr.get_value());
    });

    $(root_element).find('#hr-toggle-btn').on('click', function() {
        show_all_hr = !show_all_hr;
        render_hr_table_view(hr_cache);
    });
}

function fetch_hr_data(from, to, emp) {
    root_element.querySelector('#hr-table-container').innerHTML = `<div style="padding:40px; text-align:center;"><i class="fa fa-spinner fa-spin fa-2x"></i></div>`;
    frappe.call({
        // THE FIX: Pointing to the new, unified backend function
        method: 'mobile_app_360ithub.custom_hr.get_hr_absent_dashboard_data',
        args: { from_date: from, to_date: to, employee: emp, sort_order: current_sort_hr },
        callback: function(r) {
            hr_cache = r.message || {data:[], from_date: from, to_date: to};
            render_hr_table_view(hr_cache);
        }
    });
}

function render_hr_table_view(res) {
    var container = root_element.querySelector('#hr-table-container');
    var countLbl = root_element.querySelector('#hr-count');
    var rangeLbl = root_element.querySelector('#hr-range-text');
    var toggleBtn = root_element.querySelector('#hr-toggle-btn');

    var fmt = function(d) { return d.split('-').reverse().join('-'); };
    countLbl.innerHTML = `(${res.data ? res.data.length : 0} Pending)`;
    rangeLbl.innerHTML = `${fmt(res.from_date)} to ${fmt(res.to_date)}`;
    toggleBtn.textContent = show_all_hr ? "Show Top 5" : "Show All";

    var rows = show_all_hr ? res.data : res.data.slice(0, 5);

    var html = `
        <table class="table table-bordered" style="font-size:13.5px; background: white; margin-bottom: 0; table-layout: fixed; ">
            <thead>
                <tr style="background:#3498DB; color:white;">
                    <th style="width:50px; text-align:center; padding: 12px 8px;">SI</th>
                    <th id="emp-date-sort" style="width:110px; padding: 12px 8px; cursor:pointer;">
                        Date ${current_sort_hr === 'asc' ? '↑' : '↓'}
                    </th>
                    <th style="width:170px; padding: 12px 8px;">Employee</th>
                    <th style="padding: 12px 8px;">Check-In <i class="fa fa-sign-in" style="margin-right: 4px; opacity: 0.8;"></i>/<br>Check-Out <i class="fa fa-sign-out" style="margin-right: 4px; opacity: 0.8;"></i></th>
                    <th style="width:80px; text-align:center; padding: 12px 8px;">Hours</th>
                    <th style="width:200px; padding: 12px 8px;">Remarks</th>
                    <th style="width:170px; text-align: center; padding: 12px 8px;">Actions</th>
                </tr>
            </thead>
            <tbody>`;

    if (rows.length === 0) {
        html += `<tr><td colspan="7" style="text-align:center; padding:40px; color:#888;">No records found.</td></tr>`;
    } else {
        rows.forEach(function(row, i) {
            var actions = `<div style="display:flex; flex-direction:column; gap:4px;">`;
            
            // --- THE FIX: Updated rendering logic identical to the Employee dashboard ---
            // 1. RENDER EXISTING LEAVE BUTTON(S)
            if (row.leave_name) {
                var leave_list = row.leave_name.split(', ');
                var status_list = row.leave_status.split(', ');
                leave_list.forEach(function(l_name, index) {
                    var current_status = status_list[index];
                    var is_ok = current_status === 'Approved';
                    var is_rejected = current_status === 'Rejected';
                    var btn_class = is_rejected ? 'btn-danger' : (is_ok ? 'btn-success' : 'btn-warning');
                    var icon = is_ok ? 'fa-check-circle' : (is_rejected ? 'fa-times-circle' : 'fa-clock-o');
                    actions += `<button class="btn ${btn_class} btn-xs btn-open" data-type="Leave Application" data-name="${l_name}" style="font-weight:bold; border:none; font-size: 11px; padding: 3px; color:#fff"><i class="fa ${icon}"></i> Leave: ${current_status}</button>`;
                });
            }
            
            // 2. RENDER EXISTING ARQ BUTTON
            if (row.arq_name) {
                var is_ok = row.arq_status === 'Submitted';
                var is_rejected = row.arq_status === 'Rejected';
                var btn_class = is_rejected ? 'btn-danger' : (is_ok ? 'btn-success' : 'btn-warning');
                actions += `<button class="btn ${btn_class} btn-xs btn-open" data-type="Attendance Request" data-name="${row.arq_name}" style="font-weight:bold; border:none; font-size: 11px; padding: 3px; color:#fff"><i class="fa ${is_ok?'fa-check-circle':(is_rejected?'fa-times-circle':'fa-clock-o')}"></i> On-Duty Req: ${row.arq_status}</button>`;
            }
            
            // 3. DROPDOWN VISIBILITY LOGIC
            var has_both_half_docs = row.leave_name && row.arq_name;
            var day_fully_covered = row.is_full_day_doc || has_both_half_docs;
            
            if (!day_fully_covered) {
                var can_apply_leave = !row.leave_name || !row.leave_name.includes(',');
                var can_apply_arq = !row.arq_name;
                if (can_apply_leave || can_apply_arq) {
                    actions += `<select class="action-sel form-control" data-date="${row.date}" style="height:28px; font-size:11px; border: 1px solid #bbb; padding: 0 5px;">
                        <option value="">-- Apply --</option>
                        ${can_apply_leave ? `<option value="leave|${row.employee}|${row.employee_name}">Apply Leave</option>` : ''}
                        ${can_apply_arq ? `<option value="arq|${row.employee}|${row.employee_name}">Apply On-Duty Req</option>` : ''}
                    </select>`;
                }
            }
            actions += `</div>`;

            html += `<tr>
                <td style="text-align:center;">${i+1}</td>
                <td>${fmt(row.date)}</td>
                <td>
                    <b>${row.employee_name}</b><br>
                    <small class="text-muted">${row.employee}</small>
                </td>
                <td>${format_logs_html(row.logs)}</td>
                <td style="text-align:center;"><b>${row.hours}h</b></td>
                <td><div style="color:#e74c3c; font-weight:700;">${row.remark}</div></td>
                <td>${actions}</td>
            </tr>`;
        });
    }
    html += `</tbody></table>`;
    container.innerHTML = html;
    
    // Attach event listeners
    $(container).find('#hr-date-sort').on('click', function () {
        current_sort_hr = current_sort_hr === 'asc' ? 'desc' : 'asc';
        var val = date_ctrl_hr.get_value();
        fetch_hr_data(val[0], val[1], emp_ctrl_hr.get_value());
    });

    $(container).find('.btn-open').on('click', function() {
        window.open(frappe.utils.get_form_link($(this).data('type'), $(this).data('name')), '_blank');
    });

    $(container).find('.action-sel').on('change', function() {
        var val = $(this).val(); 
        if(!val) return;
        var date = $(this).data('date');
        var parts = val.split('|');
        var doctype = parts[0] === 'leave' ? 'Leave Application' : 'Attendance Request';
        var url = `/app/${frappe.router.slug(doctype)}/new?employee=${parts[1]}&employee_name=${encodeURIComponent(parts[2])}&from_date=${date}&to_date=${date}`;
        window.open(url, '_blank');
        $(this).val("");
    });
}




function format_logs_html(logs) {
    if (!logs || logs.length === 0) {
        return '<div style="color: #adb5bd; font-style: italic; font-size: 12px;">No Checkins</div>';
    }

    // Container with Flexbox to allow logs to sit side-by-side
    var html = `<div style="display: flex; flex-wrap: wrap; gap: 4px; align-items: center; min-width: 180px;">`;

    html += logs.map(l => {
        var is_in = l.log_type === 'IN';
        
        // Modern Soft Styling
        var bgColor = is_in ? '#def7ec' : '#e1effe';
        var textColor = is_in ? '#03543f' : '#1e429f';
        var icon = is_in ? 'fa-sign-in' : 'fa-sign-out';
        console.log("Log Type",l.log_type,icon)
        
        // Format time to HH:mm
        var time = l.time.split(' ')[1].substring(0, 5);
        
        // Discreet System Generated Indicator
        var sys_gen = l.system_generated 
            ? `<i class="fa fa-laptop" title="System Generated" style="margin-left: 4px; color: #7e3af2; font-size: 10px;"></i>` 
            : '';

        return `
            <div style="
                background-color: ${bgColor}; 
                color: ${textColor}; 
                padding: 2px 8px; 
                border-radius: 12px; 
                font-size: 11px; 
                font-weight: 600; 
                display: flex; 
                align-items: center; 
                border: 1px solid rgba(0,0,0,0.05);
                white-space: nowrap;
                cursor: default;
            " title="${l.log_type}: ${l.time}">
                <i class="fa ${icon}" style="margin-right: 4px; opacity: 0.8;"></i>
                ${time}
                ${sys_gen}
            </div>
        `;
    }).join('');

    html += `</div>`;
    return html;
}

