            greetingElement.textContent = greetingMessage;

            greetingContainer.appendChild(greetingElement);

            // Call to get the last check-in details
            frappe.call({
                method: 'mobile_app_360ithub.custom_attendance.erp_last_checkin',
                args: {},
                callback: function(rChkin) {
                    if (rChkin.message) {
                        console.log(rChkin.message)
                        // Create elements to display the last check-in details
                        var checkinContainer = document.createElement('div');
                        checkinContainer.setAttribute("style", "margin-left: 20px; display: flex; align-items: center;");

                        var checkinMessage = document.createElement('p');
                        // checkinMessage.setAttribute("style", "margin-right: 10px;");

                        var checkinButton = document.createElement('button');
                        checkinButton.setAttribute("class", "btn btn-primary");

                        if (rChkin.message.status) {
                            if (rChkin.message.type == "IN") {
                                checkinButton.textContent = "Check-In";
                            } else {
                                checkinButton.textContent = "Check-Out";
