                        checkinButton.onclick = function() {
                            // performCheckin();
                        };


                        // checkinContainer.appendChild(checkinButton);
                        checkinContainer.appendChild(checkinMessage);
                        greetingContainer.appendChild(checkinContainer);
                    }
                }
            });

            container.appendChild(greetingContainer);
        }
    }
});

function getGreeting(employeeName) {
    var now = new Date();
    var hours = now.getHours();
    var greeting;

    if (hours < 12) {
        greeting = "Good Morning, " + employeeName;
    } else if (hours < 17) {
        greeting = "Good Afternoon, " + employeeName;
    } else {
        greeting = "Good Evening, " + employeeName;
    }

    return greeting;
}

function formatDateTime(dateTimeStr) {
    var date = new Date(dateTimeStr);

    var day = date.getDate().toString().padStart(2, '0');
    var month = (date.getMonth() + 1).toString().padStart(2, '0'); // Months are zero-based
    var year = date.getFullYear();

    var hours = date.getHours().toString().padStart(2, '0');
    var minutes = date.getMinutes().toString().padStart(2, '0');

    return `${day}-${month}-${year} ${hours}:${minutes}`;
}

// Function to format date from YYYY-MM-DD to DD-MM-YYYY
function formatDate(dateStr) {
    if (!dateStr || dateStr.split('-').length !== 3) return "-";
    var parts = dateStr.split('-');
    return parts[2] + '-' + parts[1] + '-' + parts[0];
}

// Make the Frappe call for Pending Leaves
frappe.call({
    method: 'mobile_app_360ithub.custom_hr.get_unapproved_leave_applications_hr',
    callback: function(r) {
        var container = root_element.querySelector('.leave-history-table');
        container.innerHTML = ''; // Clear previous table or message

        var leave_history = (r.message && Array.isArray(r.message)) ? r.message : [];
        var msglength = leave_history.length;

        // 1. ALWAYS Create the heading
        var heading = document.createElement('h3');
        heading.textContent = `(${msglength}) Pending Leave Applications:`;
        container.appendChild(heading);

        if (msglength > 0) {
            // 2. Create the table
            var table = document.createElement('table');
            table.classList.add('table', 'table-bordered');

            // Header row
            var thead = document.createElement('thead');
            var headerRow = document.createElement('tr');
            var headers = ['S.No', 'Employee Name', "Reporting Manager", 'From Date', 'To Date', 'Total Leave Days', 'Posting Date'];

            headers.forEach(function(header) {
                var th = document.createElement('th');
                th.setAttribute("style", "background-color:#3498DB;color:white;text-align:left;border:solid 2px #bcb9b4;padding: 8px;");
                th.textContent = header;
                headerRow.appendChild(th);
            });
            thead.appendChild(headerRow);
            table.appendChild(thead);

            // Body rows
            var tbody = document.createElement('tbody');
            leave_history.forEach(function(leave, index) {
                var row = document.createElement('tr');

                // Helper to create standard cells
                const createCell = (text) => {
                    var cell = document.createElement('td');
                    cell.textContent = text || '-';
                    cell.setAttribute("style", "border:solid 2px #bcb9b4;padding: 8px;");
                    return cell;
                };

                // Cell 1: S.No
                row.appendChild(createCell(index + 1));

                // Cell 2: Employee Name with Link
                var nameCell = document.createElement('td');
                nameCell.setAttribute('style', 'border:solid 2px #bcb9b4;padding: 8px;');
                var link = document.createElement('a');
                link.textContent = leave.employee_name;
                // Using relative path /app/... is safer than hardcoding the domain
                link.setAttribute('href', '/app/leave-application/' + leave.name);
                link.setAttribute('target', '_blank');
                link.setAttribute('style', 'font-weight: bold; color: #1B4F72;');
                nameCell.appendChild(link);
                row.appendChild(nameCell);

                // Cell 3: Reporting Manager
                row.appendChild(createCell(leave.leave_approver_name));

                // Cell 4: From Date
                row.appendChild(createCell(formatDate(leave.from_date)));

                // Cell 5: To Date
                row.appendChild(createCell(formatDate(leave.to_date)));

                // Cell 6: Total Leave Days
                row.appendChild(createCell(leave.total_leave_days));

                // Cell 7: Posting Date
                row.appendChild(createCell(formatDate(leave.posting_date)));

                tbody.appendChild(row);
            });
            table.appendChild(tbody);
            container.appendChild(table);

        } else {
            // 3. Placeholder for No Pending Leaves
            var placeholder = document.createElement('div');
            placeholder.setAttribute("style", "padding: 30px; text-align: center; color: #888; border: 1px dashed #bcb9b4; border-radius: 4px; background-color: #f9f9f9; margin-top: 10px;");
            placeholder.innerHTML = `
                <div style="font-weight: 500;">No pending leave applications</div>
                <div style="font-size: 0.9em;">All catch-ups are complete!</div>
            `;
            container.appendChild(placeholder);
        }
    }
});

