// initialize_hr_absent_block();


// ***************************************

// Function to format date
function formatArqDate(dateStr) {
    if (!dateStr) return "-";
    var parts = dateStr.split('-');
    return parts[2] + '-' + parts[1] + '-' + parts[0];
}

// Target the container inside this specific block
var container = root_element.querySelector('.arq-pending-table');
container.innerHTML = '<div style="padding:10px; color:#666;"><i class="fa fa-spinner fa-spin"></i> Loading On-duty Requests...</div>';

frappe.call({
    method: 'mobile_app_360ithub.custom_employee.get_my_pending_arq',
    callback: function(r) {
        container.innerHTML = ''; 
        var data = (r.message && Array.isArray(r.message)) ? r.message : [];
        var count = data.length;

        // Heading
        var heading = document.createElement('h3');
        heading.style.margin = "0 0 15px 0";
        heading.style.fontSize = "18px";
        heading.style.fontWeight = "bold";
        heading.style.color = "#172B4D";
        heading.textContent = `(${count}) Pending On-duty Requests:`;
        container.appendChild(heading);

        if (count > 0) {
            var table = document.createElement('table');
            table.classList.add('table', 'table-bordered');
            table.setAttribute("style", "width:100%; border-collapse: collapse; background: white; font-size: 13px;");

            var thead = document.createElement('thead');
            thead.innerHTML = `
                <tr style="background-color:#3498DB; color:white;">
                    <th style="padding: 10px; border:1px solid #d1d8dd;">S.No</th>
                    <th style="padding: 10px; border:1px solid #d1d8dd;">ID</th>
                    <th style="padding: 10px; border:1px solid #d1d8dd;">Employee</th>
                    <th style="padding: 10px; border:1px solid #d1d8dd;">Approver</th>
                    <th style="padding: 10px; border:1px solid #d1d8dd;">Date</th>
                    <th style="padding: 10px; border:1px solid #d1d8dd;">Action</th>
                </tr>
            `;
            table.appendChild(thead);

            var tbody = document.createElement('tbody');
            data.forEach(function(req, index) {
                var row = document.createElement('tr');
                
                // Determine if we show the Approve button or just text
                var actionHtml = "";
                if (req.is_approver) {
                    actionHtml = `<button class="btn btn-success btn-xs" style="font-weight:bold;" onclick="window.open('/app/attendance-request/${req.name}', '_blank')">Review & Approve</button>`;
                } else {
                    actionHtml = `<span style="color:#888; font-style:italic;">Waiting Approver</span>`;
                }

                row.innerHTML = `
                    <td style="padding: 10px; border:1px solid #d1d8dd; text-align:center;">${index + 1}</td>
                    <td style="padding: 10px; border:1px solid #d1d8dd;"><a href="/app/attendance-request/${req.name}" target="_blank" style="font-weight:bold;">${req.name}</a></td>
                    <td style="padding: 10px; border:1px solid #d1d8dd;">${req.employee_name}</td>
                    <td style="padding: 10px; border:1px solid #d1d8dd;">${req.approver_display_name}</td>
                    <td style="padding: 10px; border:1px solid #d1d8dd;">${formatArqDate(req.from_date)}</td>
                    <td style="padding: 10px; border:1px solid #d1d8dd; text-align:center;">${actionHtml}</td>
                `;
                tbody.appendChild(row);
            });
            table.appendChild(tbody);
            container.appendChild(table);
        } else {
            // This will show if the database is empty
            container.innerHTML += `<div style="padding: 20px; text-align: center; color: #888; border: 1px dashed #ccc; background: #fafafa;">No pending On-duty requests found.</div>`;
        }
    }
});

// Re-using your existing formatDate function
function formatDate(dateStr) {
    if (!dateStr) return "-";

    // Split by space and take the first part (strips the 11:10:13 portion)
    var dateOnly = dateStr.toString().split(' ')[0];

    var parts = dateOnly.split('-');
    if (parts.length !== 3) return "-";

    // Reformat YYYY-MM-DD to DD-MM-YYYY
    return parts[2] + '-' + parts[1] + '-' + parts[0];
}

function formatOTTime(decimalHours) {
    if (!decimalHours || isNaN(decimalHours)) return "0h 00m";

    var hours = Math.floor(decimalHours);
    var minutes = Math.round((decimalHours - hours) * 60);

    // Ensure minutes always show two digits (e.g., 05 instead of 5)
    var paddedMinutes = minutes < 10 ? '0' + minutes : minutes;

    return hours + "h " + paddedMinutes + "m";
}
// Make the Frappe call for Overtime Requests
frappe.call({
    method: 'shantala_chits_360ithub.custom_employee.get_my_pending_overtime_requests',
    callback: function(r) {
        var container = root_element.querySelector('.ot-history-table');
        container.innerHTML = ''; 

        var ot_history = (r.message && Array.isArray(r.message)) ? r.message : [];
        var msglength = ot_history.length;

        var heading = document.createElement('h3');
        heading.style.marginBottom = "15px";
        heading.textContent = `(${msglength}) Pending / To-Approve Overtime:`;
        container.appendChild(heading);

        if (msglength > 0) {
            var table = document.createElement('table');
            table.classList.add('table', 'table-bordered');
            table.setAttribute("style", "width:100%; border-collapse: collapse;");

            var thead = document.createElement('thead');
            var headerRow = document.createElement('tr');
            // Added "Employee" and "Action" headers
            var headers = ['S.No', 'ID', 'Employee', "Approver", 'OT Date', 'OT Hours', 'Action'];

            headers.forEach(function(header) {
                var th = document.createElement('th');
                th.setAttribute("style", "background-color:#3498DB; color:white; text-align:left; border:solid 1px #d1d8dd; padding: 10px; font-size: 13px;");
                th.textContent = header;
                headerRow.appendChild(th);
            });
            thead.appendChild(headerRow);
            table.appendChild(thead);

            var tbody = document.createElement('tbody');
            ot_history.forEach(function(ot, index) {
                var row = document.createElement('tr');

                const createCell = (text, customStyle = "") => {
                    var cell = document.createElement('td');
                    cell.textContent = text || '-';
                    cell.setAttribute("style", "border:solid 1px #d1d8dd; padding: 10px; font-size: 13px; " + customStyle);
                    return cell;
                };

                // 1. S.No
                row.appendChild(createCell(index + 1));

                // 2. ID with Link
                var nameCell = document.createElement('td');
                nameCell.setAttribute('style', 'border:solid 1px #d1d8dd; padding: 10px;');
                var link = document.createElement('a');
                link.textContent = ot.name;
                link.setAttribute('href', '/app/overtime-request/' + ot.name);
                link.setAttribute('target', '_blank');
                link.setAttribute('style', 'font-weight: bold; color: #1B4F72;');
                nameCell.appendChild(link);
                row.appendChild(nameCell);

                // 3. Employee Name (Who requested it)
                row.appendChild(createCell(ot.employee_name));

                // 4. Approver Name
                row.appendChild(createCell(ot.approver_display_name));

                // 5. OT Date
                row.appendChild(createCell(formatDate(ot.date)));

                // 6. OT Hours
                row.appendChild(createCell(formatOTTime(ot.overtime_hours)));

                // 7. Action Cell
                var actionCell = document.createElement('td');
                actionCell.setAttribute('style', 'border:solid 1px #d1d8dd; padding: 10px; text-align: center;');

                if (ot.is_approver) {
                    // Show Approve Button if current user is the designated approver
                    var btn = document.createElement('button');
                    btn.innerHTML = '<i class="fa fa-check-circle"></i> Review & Approve';
                    btn.className = "btn btn-success btn-xs";
                    btn.setAttribute('style', 'font-weight: bold; padding: 4px 8px; font-size: 11px;');
                    btn.onclick = function() {
                        window.open('/app/overtime-request/' + ot.name, '_blank');
                    };
                    actionCell.appendChild(btn);
                } else {
                    // Just status text if user is the requester
                    var span = document.createElement('span');
                    span.textContent = "Waiting Approver";
                    span.className = "text-muted";
                    span.style.fontSize = "11px";
                    actionCell.appendChild(span);
                }
                row.appendChild(actionCell);

                tbody.appendChild(row);
            });
            table.appendChild(tbody);
            container.appendChild(table);

        } else {
            var placeholder = document.createElement('div');
            placeholder.setAttribute("style", "padding: 30px; text-align: center; color: #888; border: 1px dashed #bcb9b4; border-radius: 4px; background-color: #f9f9f9; margin-top: 10px;");
            placeholder.innerHTML = `
                <div style="font-weight: 500;">No pending or approval requests</div>
                <div style="font-size: 0.9em;">Everything is cleared!</div>
            `;
            container.appendChild(placeholder);
        }
    }
});

