frappe.call({
    method: 'mobile_app_360ithub.custom_employee.get_employees_present_today',
    callback: function(r) {
        var container = root_element.querySelector('.present-table');

        // Clear previous table or message
        container.innerHTML = '';

        // Get the present summary
        var present_summary = r.message || [];
        var present_count = present_summary.length;

        // Create the heading with the total count
        var heading = document.createElement('h3');
        heading.textContent = `(${present_count}) Today's Team Presence:`;
        container.appendChild(heading);

        if (present_count > 0) {
            // Create a new table
            var table = document.createElement('table');
            table.classList.add('table', 'table-bordered'); // Add Bootstrap table classes
            table.style.textAlign = 'center'; // Align text in table center

            // Add table headers
            var thead = document.createElement('thead');
            var headerRow = document.createElement('tr');
            ['Employee Name', 'First Check-In Time', 'Last Check-Out Time', 'Total Break Hours','Late'].forEach(function(headerText) {
                var th = document.createElement('th');
                th.textContent = headerText;
                th.setAttribute("style", "background-color:#3498DB;color:white;border:solid 2px #bcb9b4;padding: 8px;"); // Apply custom styling
                headerRow.appendChild(th);
            });
            thead.appendChild(headerRow);
            table.appendChild(thead);

            // Add table body
            var tbody = document.createElement('tbody');
            present_summary.forEach(function(employee) {
                var row = document.createElement('tr');

                // Iterate through the keys for each employee
                ['employee_name', 'first_in', 'last_out', 'total_break_hours','late_minutes'].forEach(function(key) {
                    var cell = document.createElement('td');

                    // For break hours, display them as "Xh Ym"
                    if (key === 'total_break_hours') {
                        cell.textContent = employee[key] ? employee[key] : '0h 0m'; // Default if no breaks
                    }else if (key === 'first_in' || key === 'last_out') {
                        // Extract only the time portion (HH:MM) from the datetime value
                        var time = employee[key] ? employee[key].split(' ')[1].substring(0, 5) : '-';  // Extract time (HH:MM)
                        cell.textContent = time;
                    } else {
                        // Display time as it is (formatted as HH:MM from Python side)
                        cell.textContent = employee[key] || '-';  // Display '-' if null
                    }

                    cell.setAttribute("style", "border:solid 2px #bcb9b4;padding: 8px;"); // Apply custom styling
                    row.appendChild(cell);
                });

                tbody.appendChild(row);
            });

            table.appendChild(tbody);

            // Append table to container
            container.appendChild(table);
        } else {
            // Handle case when no data is returned
            var noDataMessage = document.createElement('p');
            noDataMessage.textContent = 'No Employees Present.';
            container.appendChild(noDataMessage);
        }
    }
});

