script:
var current_sort_emp = "desc";
var date_ctrl_emp = null;
var show_all_emp = false;
var emp_cache = {data: []};

function init_emp_dashboard() {
    var container = root_element.querySelector('.absent-table-hr');
    container.style.padding = "10px";

    container.innerHTML = `
        <div id="emp-header" style="margin-bottom: 15px;">
            <h3 style="margin: 0 0 12px 0; font-size: 20px; font-weight: bold; color: #172B4D;">
                <span id="emp-count" style="color:#e74c3c;">(0 Action Needed)</span> Absences 
                <span id="emp-range-text" style="font-weight: normal; color: #444; margin-left: 8px; font-size: 18px;"></span>
            </h3>

            <div style="display: flex; align-items: center; gap: 10px; flex-wrap: nowrap;">
                <button id="emp-toggle-btn" class="btn btn-default btn-xs" style="font-weight:bold; color:#444; border: 1px solid #ccc; font-size: 13px; padding: 4px 12px; height: 32px;">Show Full Month</button>

                <div style="display: flex; align-items: center; gap: 10px; margin-left: auto;">
                    <div id="emp-date-filter" style="width:230px;"></div>
                    <button id="emp-apply" class="btn btn-primary btn-sm" style="height:32px; padding: 0 15px; font-weight:bold; background-color: #171717; border: none; color:white;">Apply</button>
                </div>
            </div>
        </div>

        <div id="emp-table-container"></div>
    `;

    date_ctrl_emp = frappe.ui.form.make_control({
        df: { fieldtype: 'DateRange', placeholder: 'Select Date Range' },
        parent: root_element.querySelector('#emp-date-filter'),
        render_input: true
    });

    var today = frappe.datetime.get_today();
    var month_start = frappe.datetime.month_start();
    date_ctrl_emp.set_value([month_start, today]);

    fetch_emp_data(month_start, today);

    $(root_element).find('#emp-apply').on('click', function() {
        var val = date_ctrl_emp.get_value();
        fetch_emp_data(val[0], val[1]);
    });

    $(root_element).find('#emp-toggle-btn').on('click', function() {
        show_all_emp = !show_all_emp;
        render_emp_table_view(emp_cache);
    });
}

function fetch_emp_data(from, to) {
    root_element.querySelector('#emp-table-container').innerHTML = `<div style="padding:40px; text-align:center;"><i class="fa fa-spinner fa-spin fa-2x"></i></div>`;
    frappe.call({
        method: 'mobile_app_360ithub.custom_employee.get_my_absents_formatted',
        args: { from_date: from, to_date: to, sort_order: current_sort_emp },
        callback: function(r) {
            emp_cache = r.message || {data:[], from_date: from, to_date: to};
            render_emp_table_view(emp_cache);
        }
    });
}

function render_emp_table_view(res) {
    var container = root_element.querySelector('#emp-table-container');
    var countLbl = root_element.querySelector('#emp-count');
    var rangeLbl = root_element.querySelector('#emp-range-text');
    var toggleBtn = root_element.querySelector('#emp-toggle-btn');

    var fmt = function(d) { return d.split('-').reverse().join('-'); };
    countLbl.innerHTML = `(${res.data ? res.data.length : 0} Action Needed)`;
    rangeLbl.innerHTML = `${fmt(res.from_date)} to ${fmt(res.to_date)}`;
    toggleBtn.textContent = show_all_emp ? "Hide Full Month" : "Show Full Month";

    var rows = show_all_emp ? res.data : res.data.slice(0, 2);

    var html = `
        <table class="table table-bordered" style="font-size:15px; background: white; border: 1px solid #d1d8dd;">
            <thead>
                <tr style="background:#3498DB; color:white;">
                    <th style="width:50px; text-align:center; padding: 12px 8px;">SI</th>
                    <th id="emp-date-sort" style="width:110px; padding: 12px 8px; cursor:pointer;">
                        Date ${current_sort_emp === 'asc' ? '↑' : '↓'}
                    </th>
                    <th style="width:200px; padding: 12px 8px;">Employee</th>
                    <th style="padding: 12px 8px;">Check-In <i class="fa fa-sign-in" style="margin-right: 4px; opacity: 0.8;"></i>/<br>Check-Out <i class="fa fa-sign-out" style="margin-right: 4px; opacity: 0.8;"></i></th>
                    <th style="width:80px; text-align:center; padding: 12px 8px;">Hours</th>
                    <th style="width:230px; padding: 12px 8px;">Remarks</th>
                    <th style="width:190px; text-align: center; padding: 12px 8px;">Actions</th>
                </tr>
            </thead>
            <tbody>`;

    if (rows.length === 0) {
        html += `<tr><td colspan="7" style="text-align:center; padding:40px; color:#27ae60; font-style: italic;"><i class="fa fa-check-circle"></i> No pending absences.</td></tr>`;
    } else {
        rows.forEach(function(row, i) {

            var actions = `<div style="display:flex; flex-direction:column; gap:6px;">`;

            // 1. RENDER EXISTING LEAVE BUTTON(S)
            if (row.leave_name) {
                var leave_list = row.leave_name.split(', ');
                var status_list = row.leave_status.split(', '); // Split the statuses to match!

                leave_list.forEach(function(l_name, index) {
                    var current_status = status_list[index]; // Get the specific status for this leave
                    var is_ok = current_status === 'Approved';
                    var is_rejected = current_status === 'Rejected';

                    var btn_class = is_rejected ? 'btn-danger' : (is_ok ? 'btn-success' : 'btn-warning');
                    var icon = is_ok ? 'fa-check-circle' : (is_rejected ? 'fa-times-circle' : 'fa-clock-o');

                    actions += `<button class="btn ${btn_class} btn-xs btn-open" data-type="Leave Application" data-name="${l_name}" style="font-weight:bold; border:none; font-size: 12px; padding: 5px; color:#fff"><i class="fa ${icon}"></i> Leave: ${current_status}</button>`;
                });
            }

            // 2. RENDER EXISTING ARQ BUTTON
            if (row.arq_name) {
                var is_ok = row.arq_status === 'Submitted';
                var is_rejected = row.arq_status === 'Rejected';

                // Change color to danger/red if rejected
                var btn_class = is_rejected ? 'btn-danger' : (is_ok ? 'btn-success' : 'btn-warning');

                actions += `<button class="btn ${btn_class} btn-xs btn-open" data-type="Attendance Request" data-name="${row.arq_name}" style="font-weight:bold; border:none; font-size: 12px; padding: 5px; color:#fff"><i class="fa ${is_ok?'fa-check-circle':(is_rejected?'fa-times-circle':'fa-clock-o')}"></i> On-Duty Req: ${row.arq_status}</button>`;
            }

            // 3. DROPDOWN VISIBILITY LOGIC
            var has_both_half_docs = row.leave_name && row.arq_name;
            var day_fully_covered = row.is_full_day_doc || has_both_half_docs;

            // Only show dropdown if the day is not fully covered
            if (!day_fully_covered) {

                // RULE: Can apply leave if NO leave exists, OR if only ONE leave exists (no commas)
                var can_apply_leave = !row.leave_name || !row.leave_name.includes(',');

                // RULE: Can apply ARQ ONLY if NO ARQ exists (1 day = 1 request max)
                // Note: If an ARQ exists but is Rejected, they must click the button above to cancel it first.
                var can_apply_arq = !row.arq_name;

                if (can_apply_leave || can_apply_arq) {
                    actions += `<select class="action-sel form-control" data-date="${row.date}" style="height:32px; font-size:12px; border: 1px solid #bbb;">
                        <option value="">-- Apply Missing --</option>
                        ${can_apply_leave ? `<option value="leave|${row.employee}|${row.employee_name}">Apply Leave</option>` : ''}
                        ${can_apply_arq ? `<option value="arq|${row.employee}|${row.employee_name}">Apply On-Duty Req</option>` : ''}
                    </select>`;
                }
            }
            actions += `</div>`;

            html += `<tr>
                <td style="text-align:center;">${i+1}</td>
                <td>${fmt(row.date)}</td>
                <td><b>${row.employee_name}</b></td>
                <td>${format_logs_html(row.logs)}</td>
                <td style="text-align:center;"><b>${row.hours}h</b></td>
                <td><div style="color:#e74c3c; font-weight:700; font-size:14.5px; line-height:1.3;">${row.remark}</div></td>
                <td style="vertical-align:middle;">${actions}</td>
            </tr>`;
        });
    }
    html += `</tbody></table>`;
    container.innerHTML = html;

    $(container).find('#emp-date-sort').on('click', function () {
        current_sort_emp = current_sort_emp === 'asc' ? 'desc' : 'asc';

        var val = date_ctrl_emp.get_value();
        fetch_emp_data(val[0], val[1]);
    });


    $(container).find('.btn-open').on('click', function() {
        window.open(frappe.utils.get_form_link($(this).data('type'), $(this).data('name')), '_blank');
    });


    $(container).find('.action-sel').on('change', function() {
        var val = $(this).val(); 
        if(!val) return;
        var date = $(this).data('date'); // This gets the date of the row
        var parts = val.split('|');
        var doctype = parts[0] === 'leave' ? 'Leave Application' : 'Attendance Request';
        // THE UPDATED URL LOGIC:
        // This adds from_date and to_date to BOTH Leave and ARQ
        var url = `/app/${frappe.router.slug(doctype)}/new?employee=${parts[1]}&employee_name=${encodeURIComponent(parts[2])}&from_date=${date}&to_date=${date}`;
        window.open(url, '_blank');
        $(this).val("");
    });
}

function format_logs_html(logs) {
    if (!logs || logs.length === 0) {
        return '<div style="color: #adb5bd; font-style: italic; font-size: 12px;">No Checkins</div>';
    }

    // Container with Flexbox to allow logs to sit side-by-side
    var html = `<div style="display: flex; flex-wrap: wrap; gap: 4px; align-items: center; min-width: 180px;">`;

    html += logs.map(l => {
        var is_in = l.log_type === 'IN';

        // Modern Soft Styling
        var bgColor = is_in ? '#def7ec' : '#e1effe';
        var textColor = is_in ? '#03543f' : '#1e429f';
        var icon = is_in ? 'fa-sign-in' : 'fa-sign-out';
        console.log("Log Type",l.log_type,icon)

        // Format time to HH:mm
        var time = l.time.split(' ')[1].substring(0, 5);

        // Discreet System Generated Indicator
        var sys_gen = l.system_generated 
            ? `<i class="fa fa-laptop" title="System Generated" style="margin-left: 4px; color: #7e3af2; font-size: 10px;"></i>` 
            : '';

        return `
            <div style="
                background-color: ${bgColor}; 
                color: ${textColor}; 
                padding: 2px 8px; 
                border-radius: 12px; 
                font-size: 11px; 
                font-weight: 600; 
                display: flex; 
                align-items: center; 
                border: 1px solid rgba(0,0,0,0.05);
                white-space: nowrap;
                cursor: default;
            " title="${l.log_type}: ${l.time}">
                <i class="fa ${icon}" style="margin-right: 4px; opacity: 0.8;"></i>
                ${time}
                ${sys_gen}
            </div>
        `;
    }).join('');

    html += `</div>`;
    return html;
}
