frappe.call({
    method: 'mobile_app_360ithub.custom_employee.get_employees_with_birthday_in_current_month',
    callback: function(r) {
        var employees_with_events = r.message;
        if (Object.keys(employees_with_events).length > 0) {
            var container = root_element.querySelector('.birthday-table');
            container.innerHTML = '';

            var heading = document.createElement('h3');
            heading.textContent = `Celebrities of The Month:`;
            container.appendChild(heading);

            var table = document.createElement('table');
            table.classList.add('table', 'table-bordered');

            var thead = document.createElement('thead');
            var headerRow = document.createElement('tr');

            // ADDED 'Occasion' to the header array
            ['Name', 'Date', 'Occasion'].forEach(function(headerText) {
                var th = document.createElement('th');
                th.textContent = headerText;
                th.setAttribute("style", "background-color:#3498DB;color:white;text-align:left;");
                headerRow.appendChild(th);
            });
            thead.appendChild(headerRow);
            table.appendChild(thead);

            var tbody = document.createElement('tbody');
            Object.keys(employees_with_events).forEach(function(date) {
                employees_with_events[date].forEach(function(event) {
                    var row = document.createElement('tr');

                    var cellName = document.createElement('td');
                    var cellDate = document.createElement('td');
                    var cellOccasion = document.createElement('td'); // New Column

                    // 1. Set Name
                    cellName.innerHTML = event[0]; 

                    // 2. Format Date (DD-MON)
                    var dateParts = date.split('-');
                    var day = parseInt(dateParts[1], 10).toString();
                    var month = new Date(dateParts[0] + '-01').toLocaleString('default', { month: 'short' });
                    let suffix = "th";
                    if (day === '1' || day === '21' || day === '31') { suffix = "st"; } 
                    else if (day === '2' || day === '22') { suffix = "nd"; } 
                    else if (day === '3' || day === '23') { suffix = "rd"; }

                    cellDate.textContent = day + `${suffix} of ` + month;

                    // 3. Set Occasion Text and Icon
                    var icon = document.createElement('i');
                    icon.classList.add('fa', 'fa-fw'); // Added fa-fw for consistent spacing
                    icon.style.marginRight = "5px";

                    var occasionText = "";
                    if (event[1] === 'birthday') {
                        icon.classList.add('fa-birthday-cake');
                        occasionText = "Birthday";
                    } else if (event[1] === 'anniversary') {
                        icon.classList.add('fa-heart');
                        occasionText = "Wedding Anniversary";
                    } else if (event[1] === 'joining') {
                        icon.classList.add('fa-briefcase');
                        occasionText = "Work Anniversary";
                    }

                    cellOccasion.appendChild(icon);
                    cellOccasion.appendChild(document.createTextNode(occasionText));

                    // Append cells to row
                    row.appendChild(cellName);
                    row.appendChild(cellDate);
                    row.appendChild(cellOccasion);
                    tbody.appendChild(row);
                });
            });
            table.appendChild(tbody);
            container.appendChild(table);
        }
    }
});
